import {sequenceClockSettings,sequenceClockSources,validSequenceClock} from './sequence-clock.js';
const labels={game:'게임 시간',unscaled:'배율 무시',manual:'수동 · Custom',playEveryFrame:'매 프레임 · Play Every Frame'};
export function sequenceClockMarkup(data){const clock=sequenceClockSettings(data);return '<fieldset class="take-clock-fields"><legend>재생 시계</legend><label>시간 기준<select data-sequence-clock="source" aria-label="시퀀스 시간 기준">'+sequenceClockSources.map(source=>'<option value="'+source+'"'+(clock.source===source?' selected':'')+'>'+labels[source]+'</option>').join('')+'</select></label>'+(clock.source==='playEveryFrame'?'<label>프레임 유지 시간<input data-sequence-clock="secondsPerFrame" aria-label="프레임 유지 시간" type="number" min="0.001" max="60" step="0.001" value="'+clock.secondsPerFrame+'"></label>':'')+'</fieldset>';}
export function sequenceClockInput(data,input){const key=input.dataset.sequenceClock;if(!['source','secondsPerFrame'].includes(key))throw Error('시퀀스 시계 필드를 확인하세요.');const next={...data.playbackClock,[key]:key==='source'?input.value:Number(input.value)};if(!validSequenceClock(next))throw Error('시간 기준과 프레임 유지 시간(0.001~60초)을 확인하세요.');data.playbackClock=next;}
